package com.Senai.Mubak.config; import jakarta.servlet.http.*; import org.springframework.web.servlet.HandlerInterceptor; /** Protege as rotas que exigem login e restringe a área administrativa ao perfil ROOT. */ public class AuthenticationInterceptor implements HandlerInterceptor{public boolean preHandle(HttpServletRequest q,HttpServletResponse p,Object h)throws Exception{var s=q.getSession(false);if(s==null||s.getAttribute("usuarioId")==null){p.sendRedirect("/login");return false;}if(q.getRequestURI().startsWith("/admin")&&!"ROOT".equals(s.getAttribute("perfil"))){p.sendError(403);return false;}return true;}}